WITH valid_departments AS (SELECT * FROM departments WHERE dept_name NOT IN ('Sales', 'Engineering', 'Finance') AND budget < 3932000), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3217000 THEN 'high' WHEN budget >= 1625000 THEN 'mid' ELSE 'low' END AS budget_bucket, SORT_ARRAY(COLLECT_SET(location)) AS location_list, MIN(budget) AS min_budget FROM valid_departments GROUP BY CASE WHEN budget >= 3217000 THEN 'high' WHEN budget >= 1625000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, location_list, min_budget FROM budget_bucket_summary ORDER BY budget_bucket LIMIT 5;
